<script setup lang="ts">
/**
 * Bundled artwork from public/img/<name>.webp (generated by
 * scripts/generate-images.mjs). Renders nothing if the image is missing,
 * so pages still look complete without it.
 */
const props = defineProps<{ name: string, alt?: string }>()
const failed = ref(false)
const loaded = ref(false)
const src = computed(() => `${useRuntimeConfig().app.baseURL}img/${props.name}.webp`)
watch(() => props.name, () => { failed.value = false; loaded.value = false })
</script>

<template>
  <img
    v-if="!failed"
    :src="src"
    :alt="alt || ''"
    decoding="async"
    class="transition-opacity duration-700"
    :class="loaded ? 'opacity-100' : 'opacity-0'"
    @load="loaded = true"
    @error="failed = true"
  >
</template>
